    .card__board {
      background: var(--color-canvas);
      border-block-end: var(--border-light);
      border-inline-end: var(--border-light);
      color: var(--color-ink);
    }
  }

  .card__title {
    font-weight: bold;
  }

  /* Events
  /* ------------------------------------------------------------------------ */

  .events__columns {
    border-inline: none;
  }

  .events__column-header {
    background: none;
    margin: 0;
    padding-block: 1ch;
  }

  .events__time-block {
    padding: 0 1ch;

    .events__column:first-child & {
      padding-inline-start: 0;
    }

    .events__column:last-child & {
      padding-inline-end: 0;
    }
  }

  .events__none {
    padding-block: 2ch;
  }

  .event {
    --card-color: var(--color-ink) !important;

    background: var(--color-canvas);
    border: var(--border-light);
    box-shadow: none;
    break-inside: avoid;
    color: var(--color-ink);

    .avatar {
      --avatar-size: 2lh;
    }
  }

  /* Boards
  /* ------------------------------------------------------------------------ */

  .filters,
  .card--new,
  .cards__decoration,
  .card-columns:before,
  .cards--maybe:before {
    display: none;
  }

  .card-columns {
    border-block-start: var(--border-light);
    margin-block-end: 1ch;
    min-block-size: unset;
  }

