cat <<'EOF' > app/views/cards/display/preview/_boosts.html.erb
<% if card.reactions.any? %>
  <div class="card__boosts align-center gap-half flex-item-no-shrink">
    <%= icon_tag "boost" %>
    <strong><%= card.reactions.size %></strong>
  </div>
<% end %>
EOF

cat <<'EOF' > app/views/cards/display/preview/_comments.html.erb
<% comments = card.comments.by_user %>
<% if comments.any? %>
  <div class="card__comments align-center gap-half flex-item-no-shrink">
    <%= icon_tag "comment" %>
    <strong><%= comments.count %></strong>
  </div>
<% end %>
EOF

ruby -e '
# 1. reactions.css
path = "app/assets/stylesheets/reactions.css"
content = File.read(path)
content.sub!(
  "    --reaction-border-color: var(--color-ink-lighter);\n    --row-gap: 0;",
  "    --reaction-border-color: var(--color-ink-lighter);\n    --reaction-size: 2.25rem;\n    --row-gap: 0;"
)
content.sub!(
  "    margin-inline: calc(var(--column-gap) / -1);\n    z-index: 3;",
  "    margin-inline: calc(var(--column-gap) / -1);\n    z-index: 3;\n\n    @media (min-width: 640px) {\n      --reaction-size: 1.6875rem;\n    }"
)
content.sub!(
  "    inset: var(--offset) auto auto var(--offset);\n    min-inline-size: auto;",
  "    inline-size: auto;\n    inset: var(--offset) auto auto var(--offset);\n    min-inline-size: auto;"
)
File.write(path, content)

# 2. cards.css
path = "app/assets/stylesheets/cards.css"
content = File.read(path)
content.sub!(
  "    .popup {\n      inline-size: 260px;\n    }",
  "    .popup:not(.reaction__popup) {\n      inline-size: 260px;\n    }"
)
File.write(path, content)

# 3. card-perma.css
path = "app/assets/stylesheets/card-perma.css"
content = File.read(path)
content.sub!(
  "    .card {\n      --card-aspect-ratio: 2 / 0.95;\n      --lexxy-bg-color: var(--card-bg-color);\n\n      border: none;\n    }",
  "    .card {\n      --card-aspect-ratio: 2 / 0.95;\n      --lexxy-bg-color: var(--card-bg-color);\n\n      border: none;\n    }\n\n    .reactions {\n      margin-block-start: var(--block-space);\n      margin-inline: 0;\n    }"
)
File.write(path, content)

# 4. card-columns.css
path = "app/assets/stylesheets/card-columns.css"
content = File.read(path)
old_comments_css = <<-CSS
    .card__comments {
      --column-gap: 0.8ch;

      display: flex;
      margin-block-end: calc(var(--block-space) * -1.7);
      margin-inline-end: calc(var(--card-padding-inline) * -0.5);

      .icon {
        --icon-size: 1.6em;

        color: var(--card-color);
      }
    }
CSS
new_comments_css = <<-CSS
    .card__boosts,
    .card__comments {
      --column-gap: 0.8ch;

      display: flex;
      margin-block-end: calc(var(--block-space) * -1.7);
      margin-inline-start: auto;

      .icon {
        --icon-size: 1.6em;

        color: var(--card-color);
      }
    }

    .card__boosts:not(:has(+ .card__comments)),
    .card__comments {
      margin-inline-end: calc(var(--card-padding-inline) * -0.5);
    }

    .card__boosts + .card__comments {
      margin-inline-start: 0.5ch;
    }
CSS
raise "old_comments_css not found" unless content.include?(old_comments_css)
content.sub!(old_comments_css, new_comments_css)
content.sub!(
  "      .card__meta,\n      .card__comments,",
  "      .card__meta,\n      .card__boosts,\n      .card__comments,"
)
content.sub!(
  "          .card__footer,\n          .card__comments,",
  "          .card__footer,\n          .card__boosts,\n          .card__comments,"
)
File.write(path, content)

# 5. trays.css
path = "app/assets/stylesheets/trays.css"
content = File.read(path)
content.sub!(
  "    .card__steps,\n    .card__comments,",
  "    .card__steps,\n    .card__boosts,\n    .card__comments,"
)
File.write(path, content)
' && git diff app/assets/stylesheets/

